import{_ as e,o as a,c as d,a2 as s}from"./chunks/framework.BGlkWkwp.js";const f=JSON.parse('{"title":"Scale","description":"","frontmatter":{},"headers":[],"relativePath":"scale.md","filePath":"scale.md"}'),o={name:"scale.md"};function r(i,t,h,n,l,c){return a(),d("div",null,[...t[0]||(t[0]=[s('<h1 id="scale" tabindex="-1">Scale <a class="header-anchor" href="#scale" aria-label="Permalink to &quot;Scale&quot;">​</a></h1><p>Every length in kata is derived from one number, the golden ratio φ, written to three decimals: φ = 1.618. The scale turns it into three steps, seven sizes and eight type roles. The tokens are built from these values and from nothing else.</p><p>The generator is <code>src/scale/scale.mjs</code>. <code>npm run scale</code> writes its output, <code>src/tokens/scale.css</code>, which is not edited by hand. A test pins every value to four significant digits, so a change to the scale is always a deliberate, breaking change.</p><figure class="kata-example"><iframe src="/kata/examples/scale/" title="The scale, live" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/scale/" target="_blank" rel="noopener">The scale, live</a></figcaption></figure><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><p>A step is a ratio between two neighbouring values. There are three.</p><table tabindex="0"><thead><tr><th>Step</th><th>Formula</th><th>Value</th><th>Variable</th></tr></thead><tbody><tr><td>whole</td><td>φ</td><td>1.618</td><td><code>--kata-step-whole</code></td></tr><tr><td>half</td><td>√φ</td><td>1.272</td><td><code>--kata-step-half</code></td></tr><tr><td>quarter</td><td>⁴√φ</td><td>1.128</td><td><code>--kata-step-quarter</code></td></tr></tbody></table><p>The half and quarter steps are rounded to three decimals, so that each step reads as a written number. Any power of φ in quarter steps is then a product of these three numbers: whole steps first, then at most one half step and one quarter step, and a negative exponent divides. φ^1.5 is 1.618 × 1.272 = 2.058096, and φ^−0.25 is 1 ÷ 1.128. Because of the rounding, two half steps make 1.617984 rather than 1.618; the scale keeps the rounded product and does not correct it.</p><h2 id="sizes" tabindex="-1">Sizes <a class="header-anchor" href="#sizes" aria-label="Permalink to &quot;Sizes&quot;">​</a></h2><p>Seven sizes run from 1 ÷ φ³ to 1 × φ³.</p><table tabindex="0"><thead><tr><th>Size</th><th>Formula</th><th>Value</th></tr></thead><tbody><tr><td>2xs</td><td>1 ÷ φ³</td><td>0.2361</td></tr><tr><td>xs</td><td>1 ÷ φ²</td><td>0.3820</td></tr><tr><td>sm</td><td>1 ÷ φ</td><td>0.6180</td></tr><tr><td>md</td><td>1</td><td>1</td></tr><tr><td>lg</td><td>1 × φ</td><td>1.618</td></tr><tr><td>xl</td><td>1 × φ²</td><td>2.618</td></tr><tr><td>2xl</td><td>1 × φ³</td><td>4.236</td></tr></tbody></table><p>Each size exists twice. <code>--kata-size-&lt;size&gt;</code> is in em, so it follows the font size of the element that uses it; the padding of a component grows with its text. <code>--kata-size-&lt;size&gt;-rem</code> is in rem, so it follows only the root font size; the gaps of a layout, which has no text of its own, stay the same however deeply it is nested.</p><h2 id="type-roles" tabindex="-1">Type roles <a class="header-anchor" href="#type-roles" aria-label="Permalink to &quot;Type roles&quot;">​</a></h2><p>A type role fixes four values: the font size, the line height, the letter spacing and the offset.</p><ul><li>The font size is 1rem × φ^e, where the exponent e is a multiple of one quarter, built from the rounded steps as above.</li><li>The line height is a step, used as a ratio. Compact text (titles, headings, captions) uses the half step, 1.272. Running text uses the whole step, 1.618.</li><li>The letter spacing is in em. It is the one value that is not a formula: it is an optical correction measured for each size, negative for large text, which looks loose, and positive for the smallest, which looks cramped.</li><li>The offset is the font size × the line height ÷ φ. It is a distance that belongs to the text, used to place text against a baseline and to set the space between a heading and the text it introduces. For body text, whose line height is φ itself, the offset is the font size ÷ φ.</li></ul><table tabindex="0"><thead><tr><th>Role</th><th>e</th><th>Font size</th><th>Line height</th><th>Letter spacing</th><th>Offset</th></tr></thead><tbody><tr><td>display2</td><td>2</td><td>2.618rem</td><td>half</td><td>−0.022em</td><td>2.058rem</td></tr><tr><td>title1</td><td>1.5</td><td>2.058rem</td><td>half</td><td>−0.022em</td><td>1.618rem</td></tr><tr><td>title2</td><td>1</td><td>1.618rem</td><td>half</td><td>−0.02em</td><td>1.272rem</td></tr><tr><td>title3</td><td>0.5</td><td>1.272rem</td><td>half</td><td>−0.017em</td><td>1.000rem</td></tr><tr><td>heading</td><td>0.25</td><td>1.128rem</td><td>half</td><td>−0.014em</td><td>0.8868rem</td></tr><tr><td>subheading</td><td>−0.25</td><td>0.8865rem</td><td>half</td><td>−0.007em</td><td>0.6969rem</td></tr><tr><td>body</td><td>0</td><td>1rem</td><td>whole</td><td>−0.011em</td><td>0.6180rem</td></tr><tr><td>capline</td><td>−0.5</td><td>0.7862rem</td><td>half</td><td>0.0618em</td><td>0.6180rem</td></tr></tbody></table><p>The variables are <code>--kata-fs-&lt;role&gt;</code>, <code>--kata-lh-&lt;role&gt;</code>, <code>--kata-ls-&lt;role&gt;</code> and <code>--kata-offset-&lt;role&gt;</code>. Components do not use them directly: the <a href="./tokens">tokens</a> give each role of an interface (a title, body text, a caption, a label) one of these steps.</p><h2 id="changing-the-root" tabindex="-1">Changing the root <a class="header-anchor" href="#changing-the-root" aria-label="Permalink to &quot;Changing the root&quot;">​</a></h2><p>Nothing in the scale is typed in except φ and the letter spacings. Setting another root in the generator and running <code>npm run scale</code> produces a consistent scale, and every token follows. The pinned values in the tests fail on purpose when that happens.</p>',19)])])}const m=e(o,[["render",r]]);export{f as __pageData,m as default};
